import{_ as e,c as r,o,ag as d}from"./chunks/framework.bCALENAD.js";const h=JSON.parse('{"title":"数据结构","description":"","frontmatter":{},"headers":[],"relativePath":"interview/8part/dataStructure.md","filePath":"interview/8part/dataStructure.md","lastUpdated":1786959387000}'),n={name:"interview/8part/dataStructure.md"};function s(l,t,g,a,i,c){return o(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="数据结构" tabindex="-1">数据结构 <a class="header-anchor" href="#数据结构" aria-label="Permalink to &quot;数据结构&quot;">​</a></h1><h2 id="二叉树的四种遍历方式" tabindex="-1">二叉树的四种遍历方式 <a class="header-anchor" href="#二叉树的四种遍历方式" aria-label="Permalink to &quot;二叉树的四种遍历方式&quot;">​</a></h2><p>二叉树的遍历（traversing binary tree）是指从根结点出发，按照某种次序依次访问二叉树中所有的结点，使得每个结点被访问依次且仅被访问一次。</p><table tabindex="0"><thead><tr><th style="text-align:left;">遍历方式</th><th style="text-align:left;">访问顺序/规则</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>前序遍历</strong></td><td style="text-align:left;">先访问<strong>根结点</strong>，然后前序遍历<strong>左子树</strong>，再前序遍历<strong>右子树</strong>。</td></tr><tr><td style="text-align:left;"><strong>中序遍历</strong></td><td style="text-align:left;">中序遍历根结点的<strong>左子树</strong>，然后是访问<strong>根结点</strong>，最后遍历<strong>右子树</strong>。</td></tr><tr><td style="text-align:left;"><strong>后序遍历</strong></td><td style="text-align:left;">从左到右先叶子后结点的方式遍历访问<strong>左右子树</strong>，最后访问<strong>根结点</strong>。</td></tr><tr><td style="text-align:left;"><strong>层序遍历</strong></td><td style="text-align:left;">从根结点从上往下逐层遍历，在同一层，按从左到右的顺序对结点逐个访问。</td></tr></tbody></table><h2 id="数组和链表的区别" tabindex="-1">数组和链表的区别 <a class="header-anchor" href="#数组和链表的区别" aria-label="Permalink to &quot;数组和链表的区别&quot;">​</a></h2><blockquote><p><strong>核心结论</strong>：数组是<strong>连续内存</strong> + <strong>按下标随机访问</strong>，适合&quot;读多写少&quot;的场景；链表是<strong>分散内存</strong> + <strong>通过指针串起来</strong>，适合&quot;频繁插入/删除&quot;的场景。两者在内存布局、访问方式、增删效率上完全相反。</p></blockquote><table tabindex="0"><thead><tr><th style="text-align:left;">对比维度</th><th style="text-align:left;">数组</th><th style="text-align:left;">链表</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>内存布局</strong></td><td style="text-align:left;"><strong>连续</strong>内存空间</td><td style="text-align:left;"><strong>分散</strong>内存，通过指针串联</td></tr><tr><td style="text-align:left;"><strong>访问方式</strong></td><td style="text-align:left;">支持<strong>按下标随机访问</strong>，O(1)</td><td style="text-align:left;">只能<strong>顺序遍历</strong>，O(N)</td></tr><tr><td style="text-align:left;"><strong>插入/删除</strong></td><td style="text-align:left;">需要<strong>移动大量元素</strong>，O(N)</td><td style="text-align:left;">只需<strong>修改指针</strong>，O(1)</td></tr><tr><td style="text-align:left;"><strong>空间开销</strong></td><td style="text-align:left;">仅存储数据，空间利用率高</td><td style="text-align:left;">每个节点需额外存储指针，有额外开销</td></tr><tr><td style="text-align:left;"><strong>扩容方式</strong></td><td style="text-align:left;">一般需<strong>整体搬迁</strong>到更大空间</td><td style="text-align:left;">按需创建新节点，天然支持动态扩展</td></tr><tr><td style="text-align:left;"><strong>适用场景</strong></td><td style="text-align:left;"><strong>读多写少</strong>、频繁查询</td><td style="text-align:left;"><strong>频繁插入/删除</strong>、写多读少</td></tr><tr><td style="text-align:left;"><strong>典型应用</strong></td><td style="text-align:left;">数组、动态数组、哈希表底层</td><td style="text-align:left;">链表、栈、队列、邻接表、LRU 缓存</td></tr></tbody></table><h2 id="算法的时间和空间复杂度" tabindex="-1">算法的时间和空间复杂度 <a class="header-anchor" href="#算法的时间和空间复杂度" aria-label="Permalink to &quot;算法的时间和空间复杂度&quot;">​</a></h2><blockquote><p><strong>核心结论</strong>：时间复杂度衡量&quot;<strong>跑得多快</strong>&quot;，空间复杂度衡量&quot;<strong>吃多少内存</strong>&quot;。我们用 <strong>大 O 表示法</strong> 描述它们随数据规模 <code>n</code> 增长的变化趋势，<strong>忽略常数和低阶项</strong>，只看最高阶。</p></blockquote><div class="info custom-block"><p class="custom-block-title">时间复杂度（Time Complexity）</p><ul><li><strong>含义</strong>：算法执行所耗费的时间，<strong>随数据规模 <code>n</code> 的变化趋势</strong>。</li><li>大 O 表示的是<strong>最坏情况</strong>下的渐进上界。</li></ul></div><div class="info custom-block"><p class="custom-block-title">空间复杂度（Space Complexity）</p><ul><li><strong>含义</strong>：算法运行过程中<strong>临时占用</strong>的存储空间，随 <code>n</code> 的变化趋势。</li><li>包括：算法本身占的空间、输入数据的副本、额外申请的数组 / 哈希表 / 栈等。</li></ul></div><table tabindex="0"><thead><tr><th>复杂度</th><th>名称</th><th>典型算法举例</th><th>趋势感受</th></tr></thead><tbody><tr><td><strong><code>O(1)</code></strong></td><td>常数</td><td>哈希表查询、数组按下标访问</td><td>跟 <code>n</code> 无关</td></tr><tr><td><strong><code>O(log n)</code></strong></td><td>对数</td><td>二分查找、平衡树操作</td><td>增长极慢</td></tr><tr><td><strong><code>O(n)</code></strong></td><td>线性</td><td>顺序遍历、一次遍历数组</td><td>数据翻倍，时间翻倍</td></tr><tr><td><strong><code>O(n log n)</code></strong></td><td>线性对数</td><td>快排、归并排序、堆排序</td><td>主流排序算法的上限</td></tr><tr><td><strong><code>O(n²)</code></strong></td><td>平方</td><td>冒泡 / 选择 / 插入排序、双层循环</td><td><code>n</code> 翻倍，时间 ×4</td></tr><tr><td><strong><code>O(2ⁿ)</code></strong></td><td>指数</td><td>朴素斐波那契递归、子集枚举</td><td><code>n</code> 一变就爆炸</td></tr><tr><td><strong><code>O(n!)</code></strong></td><td>阶乘</td><td>全排列（暴力）、旅行商 NP 问题</td><td>完全不可承受</td></tr></tbody></table>',12)])])}const x=e(n,[["render",s]]);export{h as __pageData,x as default};
